Future<dynamic> getOfflineAirportData(String? icaoCode) async {
  if (icaoCode == null || icaoCode.trim().isEmpty) return null;

  final airport = AirportData.getAirportData(icaoCode);
  if (airport != null) {
    return airport.toMap();
  }
  return null;
}

